; seconds.asm -- chapter 33: a clock that keeps time
; generated by gen33.py
        INCLUDE "msx.inc"
        OUTPUT "seconds.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
frames  EQU VARS + 16           ; frames counted by isr
secs17  EQU VARS + 18           ; chapter 17's seconds: 50 or 60 frames each
count   EQU VARS + 20           ; frames left in chapter 17's second
rate    EQU VARS + 21           ; 50 or 60
secs    EQU VARS + 22           ; the seconds kept
part    EQU VARS + 24           ; a second's worth gathered, in shares
per     EQU VARS + 26           ; the shares of a frame: 44 or 13
full    EQU VARS + 28           ; the shares of a second: 2,207 or 779
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; Two clocks kept by the interrupt: chapter 17's, which counts 50 or 60 frames
; to a second, and one that counts 2,207 frames as 44 seconds at 50 Hz
; and 779 as 13 at 60 Hz (chapter 18). The main loop prints the frames and
; both clocks.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: none, chapter 30's set at 32
        xor a
        ld e, 1
        call fill
        ld hl, font
        ld e, 3
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names: the three labels
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld a, 60
        ld hl, 13
        ld de, 779
        jr nc, .hz
        ld a, 50
        ld hl, 44
        ld de, 2207
.hz:    ld (rate), a
        ld (count), a
        ld (per), hl
        ld (full), de
        ld hl, 0
        ld (frames), hl
        ld (secs17), hl
        ld (secs), hl
        ld (part), hl
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; the display on, and the frame's signal
        in a, (VDP_CTRL)
main:   ei
        halt                    ; wait for the frame
        di                      ; the interrupts off while the VDP is written
        ld d, 8
        ld e, 24
        call at
        ld hl, (frames)
        call digits
        ld d, 10
        ld e, 24
        call at
        ld hl, (secs17)
        call digits
        ld d, 12
        ld e, 24
        call at
        ld hl, (secs)
        call digits
        jr main

; isr: every frame. The frames; chapter 17's clock, a second every 50 or 60
; frames; and the clock that keeps time, PER shares a frame and a second every
; FULL shares. Keeps AF, DE and HL
isr:    push af
        push hl
        push de
        in a, (VDP_CTRL)        ; the status: the signal down
        ld hl, (frames)
        inc hl
        ld (frames), hl
        ld hl, count            ; chapter 17's clock
        dec (hl)
        jr nz, .kept
        ld a, (rate)
        ld (hl), a
        ld hl, (secs17)
        inc hl
.t17:   ld (secs17), hl         ; a second, chapter 17's
.kept:  ld hl, (part)           ; the clock that keeps time
        ld de, (per)
        add hl, de
        ld de, (full)
        or a
        sbc hl, de
        jr c, .not
        ld (part), hl           ; a second's shares taken off
        ld hl, (secs)
        inc hl
.tk:    ld (secs), hl           ; a second, kept
        jr .out
.not:   add hl, de              ; not a second yet
        ld (part), hl
.out:   pop de
        pop hl
        pop af
        ei
        ret

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; digits: HL as five decimal digits to the address set (chapter 30)
digits: ld bc, tens
.digit: ld a, (bc)
        ld e, a
        inc bc
        ld a, (bc)
        ld d, a
        inc bc
        ld a, '0' - 1
.count: inc a
        or a
        sbc hl, de
        jr nc, .count
        add hl, de
        out (VDP_DATA), a
        ld a, e
        dec a
        jr nz, .digit
        ret
tens:   dw 10000, 1000, 100, 10, 1

; fill: E blocks of 256 bytes of A to the VDP, after an address is set
fill:   ld b, 0
.out:   out (VDP_DATA), a
        djnz .out
        dec e
        jr nz, .out
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
